-- 0149: gateway_not_started settlement (0102) for every gateway dispatch kind. A reserved gateway send that provably never wrote a request byte (one-use preparation unused, or the in-process transport witness of connection refused / DNS failure) settles dispatched -> settled with {version,kind,dispatch} evidence equal to the row's own handle and binding (C unchanged) for AI1 legacy/AI1 item/AI2 item, the seven text routes (text profile, reason translation, product translation, product tagline ko, crawl tagline, search verify, websearch query) and local-direct (local_model_direct).
-- Like 0132, each terminal CHECK is rebuilt from its live pg_get_constraintdef predicate as the whole left side (0102's narrow branch and every later branch stay exactly as stored) plus one appended OR branch of the 0102 shape with the widened kind list; the $ai2_local$ quoting tag is the marker the schema history tests recognise for this rebuild form. No functions, triggers, indexes, grants, columns or row changes.
--> statement-breakpoint
DO $$
DECLARE old_predicate text;
BEGIN
  SELECT substring(pg_get_constraintdef(oid) FROM 7) INTO STRICT old_predicate
    FROM pg_constraint WHERE conrelid='model_capacity_requests'::regclass AND conname='model_capacity_requests_terminal_check';
  ALTER TABLE model_capacity_requests DROP CONSTRAINT model_capacity_requests_terminal_check;
  EXECUTE format('ALTER TABLE model_capacity_requests ADD CONSTRAINT model_capacity_requests_terminal_check CHECK ((%s) OR (%s))',
    old_predicate, $ai2_local$coalesce(((state='settled' AND terminal_evidence IS NOT NULL AND terminal_evidence_hash IS NOT NULL AND settled_at IS NOT NULL) AND (terminal_evidence_hash ~ '^[a-f0-9]{64}$') AND (dispatch_binding IS NOT NULL AND dispatch_binding_hash IS NOT NULL AND dispatched_at IS NOT NULL) AND (jsonb_typeof(dispatch_binding)='object') AND (dispatch_binding->'version'='1'::jsonb) AND (dispatch_binding->>'kind' IN ('ai1_legacy_gateway','ai1_item_gateway','ai2_item_gateway','text_profile_gateway','reason_translation_gateway','product_translation_gateway','product_tagline_ko_gateway','crawl_tagline_gateway','search_verify_gateway','websearch_query_gateway','local_model_direct')) AND (CASE WHEN jsonb_typeof(terminal_evidence)='object' THEN terminal_evidence ?& ARRAY['version','kind','dispatch'] AND terminal_evidence - ARRAY['version','kind','dispatch']='{}'::jsonb ELSE false END) AND (terminal_evidence->'version'='1'::jsonb) AND (terminal_evidence->'kind'='"gateway_not_started"'::jsonb) AND (terminal_evidence->'dispatch'=jsonb_build_object('requestId',request_id::text,'owner',jsonb_build_object('instanceId',owner_instance_id,'bootId',owner_boot_id::text),'token',token::text,'epoch',epoch,'revision',revision,'policyHash',policy_hash,'binding',dispatch_binding,'bindingHash',dispatch_binding_hash))),false)$ai2_local$);
END $$;
--> statement-breakpoint
DO $$
DECLARE old_predicate text;
BEGIN
  SELECT substring(pg_get_constraintdef(oid) FROM 7) INTO STRICT old_predicate
    FROM pg_constraint WHERE conrelid='model_capacity_events'::regclass AND conname='model_capacity_events_terminal_check';
  ALTER TABLE model_capacity_events DROP CONSTRAINT model_capacity_events_terminal_check;
  EXECUTE format('ALTER TABLE model_capacity_events ADD CONSTRAINT model_capacity_events_terminal_check CHECK ((%s) OR (%s))',
    old_predicate, $ai2_local$coalesce(((kind='dispatch_settled' AND evidence IS NOT NULL AND from_state='dispatched' AND to_state='settled') AND (CASE WHEN jsonb_typeof(evidence)='object' THEN evidence ?& ARRAY['version','kind','dispatch'] AND evidence - ARRAY['version','kind','dispatch']='{}'::jsonb ELSE false END) AND (evidence->'version'='1'::jsonb) AND (evidence->'kind'='"gateway_not_started"'::jsonb) AND (CASE WHEN jsonb_typeof(evidence->'dispatch')='object' THEN (evidence->'dispatch') ?& ARRAY['requestId','owner','token','epoch','revision','policyHash','binding','bindingHash'] AND (evidence->'dispatch') - ARRAY['requestId','owner','token','epoch','revision','policyHash','binding','bindingHash']='{}'::jsonb ELSE false END) AND (CASE WHEN jsonb_typeof(evidence->'dispatch'->'owner')='object' THEN (evidence->'dispatch'->'owner') ?& ARRAY['instanceId','bootId'] AND (evidence->'dispatch'->'owner') - ARRAY['instanceId','bootId']='{}'::jsonb ELSE false END) AND (jsonb_typeof(evidence->'dispatch'->'owner'->'instanceId')='string') AND (jsonb_typeof(evidence->'dispatch'->'owner'->'bootId')='string' AND (evidence->'dispatch'->'owner'->>'bootId') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') AND (jsonb_typeof(evidence->'dispatch'->'token')='string' AND (evidence->'dispatch'->>'token') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') AND (jsonb_typeof(evidence->'dispatch'->'bindingHash')='string' AND (evidence->'dispatch'->>'bindingHash') ~ '^[a-f0-9]{64}$') AND (jsonb_typeof(evidence->'dispatch'->'binding')='object') AND (evidence->'dispatch'->'binding'->'version'='1'::jsonb) AND (evidence->'dispatch'->'binding'->>'kind' IN ('ai1_legacy_gateway','ai1_item_gateway','ai2_item_gateway','text_profile_gateway','reason_translation_gateway','product_translation_gateway','product_tagline_ko_gateway','crawl_tagline_gateway','search_verify_gateway','websearch_query_gateway','local_model_direct')) AND (evidence->'dispatch'->>'requestId'=request_id::text) AND (evidence->'dispatch'->'epoch'=to_jsonb(epoch)) AND (evidence->'dispatch'->'revision'=to_jsonb(revision)) AND (evidence->'dispatch'->>'policyHash'=policy_hash)),false)$ai2_local$);
END $$;
